const normalizeArabicIndicDigits = (value: any) =>
  String(value ?? "").replace(/[٠-٩۰-۹]/g, (ch) => {
    const code = ch.charCodeAt(0);
    if (code >= 0x0660 && code <= 0x0669) return String(code - 0x0660);
    if (code >= 0x06f0 && code <= 0x06f9) return String(code - 0x06f0);
    return ch;
  });

const stripArabicIndicDigitsFromInput = (value: any) =>
  String(value ?? "").replace(/[\u0660-\u0669\u06f0-\u06f9\uff10-\uff19]/g, "");

const todayDateInputValue = () => {
  const now = new Date();
  const yyyy = now.getFullYear();
  const mm = String(now.getMonth() + 1).padStart(2, "0");
  const dd = String(now.getDate()).padStart(2, "0");
  return `${yyyy}-${mm}-${dd}`;
};

const MIRAS_ALLOWED_SUBMISSION_EXTENSIONS = [
  ".pdf",
  ".doc",
  ".docx",
  ".ppt",
  ".pptx",
  ".xls",
  ".xlsx",
  ".csv",
  ".txt",
  ".rtf",
  ".jpg",
  ".jpeg",
  ".png",
  ".webp",
  ".gif",
  ".zip",
];
const MIRAS_ALLOWED_SUBMISSION_FORMATS_LABEL =
  "PDF، Word، PowerPoint، Excel، CSV، TXT، صور JPG/PNG/WebP أو ZIP";
const MIRAS_MAX_SUBMISSION_FILE_SIZE_BYTES = 25 * 1024 * 1024;
// لا نُضمّن الملفات الكبيرة كـ base64 داخل JSON التسليم؛ الرفع سبق وحفظها
// برابط دائم. تضمين ملف PDF كبير داخل JSON هو سبب شائع لفشل الحفظ وظهور
// رسالة اتصال مضللة، رغم أن الملف نفسه مرفوع.
const MIRAS_MAX_EMBEDDED_ATTACHMENT_FILE_BYTES = 2 * 1024 * 1024;
const MIRAS_MAX_EMBEDDED_ATTACHMENT_DATA_URL_CHARS = 3_000_000;
const repairMirasMisdecodedArabicFilename = (value: any) => {
  const text = String(value || "");
  if (!/[\u0080-\u00ff]/.test(text)) return text;
  try {
    const bytes = Uint8Array.from(
      Array.from(text, (ch) => ch.charCodeAt(0) & 0xff),
    );
    const repaired = new TextDecoder("utf-8", { fatal: false }).decode(bytes);
    if (!repaired || repaired.includes("�")) return text;
    return /[\u0600-\u06ff]/.test(repaired) ? repaired : text;
  } catch {
    return text;
  }
};
const mirasCleanAttachmentName = (value: any, fallback = "مرفق") => {
  const repaired = repairMirasMisdecodedArabicFilename(value);
  const clean = String(repaired || fallback)
    .replace(/[\r\n\0]/g, "")
    .replace(/^.*[\\/]/, "")
    .trim();
  return clean || fallback;
};
const mirasFileExtension = (fileName: any) => {
  const clean = mirasCleanAttachmentName(fileName, "")
    .split(/[?#]/)[0]
    .trim()
    .toLowerCase();
  const dot = clean.lastIndexOf(".");
  return dot >= 0 ? clean.slice(dot) : "";
};
const validateMirasSubmissionFileFormat = (fileName: any) => {
  const ext = mirasFileExtension(fileName);
  if (!ext) {
    return {
      ok: false,
      message: `صيغة الملف غير معروفة. الصيغ المتاحة: ${MIRAS_ALLOWED_SUBMISSION_FORMATS_LABEL}.`,
    };
  }
  if (!MIRAS_ALLOWED_SUBMISSION_EXTENSIONS.includes(ext)) {
    return {
      ok: false,
      message: `صيغة الملف "${mirasCleanAttachmentName(fileName, "ملف")}" غير مدعومة. الصيغ المتاحة: ${MIRAS_ALLOWED_SUBMISSION_FORMATS_LABEL}.`,
    };
  }
  return { ok: true, message: "" };
};
const mirasDeadlineEndMs = (value: any) => {
  const raw = String(value || "").trim();
  if (!raw) return 0;
  const normalized = normalizeArabicIndicDigits(raw);
  const dateOnly = normalized.match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (dateOnly) {
    const [, y, m, d] = dateOnly;
    return new Date(
      Number(y),
      Number(m) - 1,
      Number(d),
      23,
      59,
      59,
      999,
    ).getTime();
  }
  const parsed = new Date(normalized).getTime();
  return Number.isFinite(parsed) ? parsed : 0;
};
const mirasIsPastDeadline = (value: any, now = Date.now()) => {
  const deadline = mirasDeadlineEndMs(value);
  return !!deadline && Number.isFinite(deadline) && now > deadline;
};

