type MirasLocalVisionMode =
  "off" | "respectful" | "low_light" | "strict" | "balanced";
type MirasCameraFailurePolicy =
  "allow_with_flag" | "teacher_review" | "block_start";

const DEFAULT_LOCAL_VISION_CONFIG = {
  enabled: false,
  mode: "strict" as MirasLocalVisionMode,
  cameraFailurePolicy: "block_start" as MirasCameraFailurePolicy,
  cameraExceptions: [] as string[],
  gazeAwaySeconds: 5,
  softLockThreshold: 2,
  teacherEscalationThreshold: 4,
};

const normalizeLocalVisionConfig = (exam: any) => {
  const raw = exam?.antiCheat?.localVision || exam?.localVision || {};
  const rawMode = String(raw.mode || "");
  const mode =
    rawMode === "balanced" || rawMode === "low_light"
      ? "strict"
      : ["off", "respectful", "strict"].includes(rawMode)
        ? (rawMode as MirasLocalVisionMode)
        : DEFAULT_LOCAL_VISION_CONFIG.mode;
  const cameraFailurePolicy = [
    "allow_with_flag",
    "teacher_review",
    "block_start",
  ].includes(String(raw.cameraFailurePolicy || ""))
    ? (String(raw.cameraFailurePolicy) as MirasCameraFailurePolicy)
    : DEFAULT_LOCAL_VISION_CONFIG.cameraFailurePolicy;
  const enabled = raw.enabled === true && mode !== "off";
  const cameraExceptions = Array.isArray(raw.cameraExceptions)
    ? raw.cameraExceptions
        .map((v: any) => String(v || "").trim())
        .filter(Boolean)
    : String(
        raw.cameraExceptionsText ||
          raw.cameraExemptions ||
          raw.cameraExceptions ||
          "",
      )
        .split(/[\n,،]+/)
        .map((v) => v.trim())
        .filter(Boolean);
  const gazeAwaySeconds = Math.max(
    3,
    Math.min(20, Math.floor(Number(raw.gazeAwaySeconds) || 5)),
  );
  const softLockThreshold = Math.max(
    1,
    Math.min(6, Math.floor(Number(raw.softLockThreshold) || 2)),
  );
  const teacherEscalationThreshold = Math.max(
    softLockThreshold,
    Math.min(12, Math.floor(Number(raw.teacherEscalationThreshold) || 4)),
  );
  return {
    enabled,
    mode,
    cameraFailurePolicy,
    gazeAwaySeconds,
    softLockThreshold,
    teacherEscalationThreshold,
    cameraExceptions,
  };
};

