const DEFAULT_ALLOWED_STUDENTS_TEXT = "";

type MirasNotifPermission = "unsupported" | "default" | "granted" | "denied";

// المصدر الوحيد للحقيقة عن حالة إذن إشعارات المتصفح. لا نخلطها مع التنبيهات
// الداخلية حتى لا نعرض للمستخدم رسالة مضللة بأن إشعارات الجهاز مفعّلة.
const readBrowserNotifPermission = (): MirasNotifPermission => {
  if (typeof window === "undefined" || !("Notification" in window))
    return "unsupported";
  try {
    return Notification.permission as MirasNotifPermission;
  } catch {
    return "unsupported";
  }
};

// سطر إرشاد واحد بسيط لإعادة التفعيل عند الحظر، يتكيّف مع iPhone/Safari/PWA.
const getMirasNotifUnblockHint = (): string => {
  if (typeof navigator === "undefined")
    return "افتح قفل الموقع واسمح بالإشعارات";
  const ua = navigator.userAgent || "";
  const isIOS =
    /iPad|iPhone|iPod/.test(ua) ||
    ((navigator as any).platform === "MacIntel" &&
      (navigator as any).maxTouchPoints > 1);
  const isStandalone =
    (typeof window !== "undefined" &&
      window.matchMedia?.("(display-mode: standalone)")?.matches) ||
    (navigator as any).standalone === true;
  if (isIOS && isStandalone) return "فعّلها من إعدادات الجهاز ثم حدّث";
  if (isIOS) return "أضف مِراس للشاشة الرئيسية ثم فعّل";
  return "افتح قفل الموقع واسمح بالإشعارات";
};

const safeUserFacingErrorText = (value: any) => {
  const text = String(value || "")
    .replace(/\s+/g, " ")
    .trim();
  if (!text) return "";
  if (
    /stack trace|at\s+\S+\s+\(|\/Users\/|node_modules|server\.ts|src\/App|TypeError:/i.test(
      text,
    )
  )
    return "";
  return text;
};

const extractApiErrorReason = (
  error: any,
  fallbackContext = "تنفيذ الإجراء",
) => {
  const context = String(fallbackContext || "تنفيذ الإجراء").trim();
  const isUploadContext = /رفع الملف|المرفق|مرفق|ملف/i.test(context);
  const isProjectSubmitContext = /تسليم المشروع|حفظ التسليم|مشروع/i.test(
    context,
  );
  const rawData =
    error?.response?.data ||
    error?.data ||
    (error && typeof error === "object" && !("message" in error)
      ? error
      : null);
  const status = Number(
    error?.response?.status ||
      error?.status ||
      error?.statusCode ||
      rawData?.status ||
      0,
  );
  const code = String(rawData?.code || error?.code || "")
    .trim()
    .toUpperCase();
  const candidates = [
    rawData?.message,
    rawData?.error,
    rawData?.reason,
    Array.isArray(rawData?.errors) ? rawData.errors.join("، ") : "",
    error?.message,
    typeof error === "string" ? error : "",
  ];
  const rawMessage =
    candidates.map(safeUserFacingErrorText).find(Boolean) || "";
  const combined = `${code} ${rawMessage}`.trim();

  if (
    /INVALID|WRONG|غير صحيح|غير صالح/.test(combined) &&
    /CODE|كود|رمز/.test(combined)
  )
    return "الكود غير صحيح.";
  if (
    /EXPIRED|منتهي|انتهت.*صلاحية/.test(combined) &&
    /CODE|كود|رمز/.test(combined)
  )
    return "الكود منتهي الصلاحية.";
  if (/USED|REDEEMED|مستخدم/.test(combined) && /CODE|كود|رمز/.test(combined))
    return "هذا الكود مستخدم مسبقًا.";
  if (
    /STUDENT_NOT_FOUND|الطالب غير موجود|لم يتم العثور على الطالب/.test(combined)
  )
    return "لم يتم العثور على الطالب.";
  if (
    /UNSUPPORTED|UNSUPPORTED_FILE_TYPE|FILE_TYPE_NOT_ALLOWED|نوع الملف|صيغة الملف|غير مدعوم|غير مسموح/.test(
      combined,
    )
  )
    return /صيغة الملف|نوع الملف/.test(rawMessage)
      ? rawMessage
      : `صيغة الملف غير مدعومة. الصيغ المتاحة: ${MIRAS_ALLOWED_SUBMISSION_FORMATS_LABEL}.`;
  if (/FILE_TOO_LARGE|حجم الملف|يتجاوز الحد/.test(combined))
    return "حجم الملف كبير. الحد الأقصى المسموح 25 ميجابايت.";
  if (
    /attachment|مرفق|الملف المطلوب/i.test(combined) &&
    /404|غير موجود|غير متوفر|تم حذفه/.test(combined)
  )
    return "تعذر تحميل المرفق من الخادم.";
  if (/timeout|ETIMEDOUT|وقتًا طويلًا|استغرق/i.test(combined))
    return "استغرق الطلب وقتًا طويلًا. حاول مرة أخرى.";
  if (
    /Failed to fetch|NetworkError|Load failed|fetch failed|network|CORS|تعذر الاتصال|الاتصال بالخادم|عطل في الاتصال/i.test(
      combined,
    )
  ) {
    if (isUploadContext)
      return "تعذر رفع الملف. تأكد من الإنترنت ثم حاول مرة أخرى.";
    if (isProjectSubmitContext)
      return "تعذر حفظ التسليم. لم يصل العمل للأستاذ، حاول مرة أخرى.";
    return "تعذر الاتصال بالخادم. تأكد من الإنترنت ثم حاول مرة أخرى.";
  }

  const genericText =
    /^(تعذر\s+إتمام\s+العملية|تعذرت\s+العملية|حدث\s+خطأ|فشل\s+الطلب|Operation\s+failed|Something\s+went\s+wrong|try\s+again)$/i;
  if (rawMessage && !genericText.test(rawMessage)) return rawMessage;

  if (status === 400) return "البيانات المدخلة غير صحيحة.";
  if (status === 401) return "انتهت الجلسة، سجّل الدخول مرة أخرى.";
  if (status === 403) return "لا تملك صلاحية تنفيذ هذا الإجراء.";
  if (status === 404) return "العنصر المطلوب غير موجود.";
  if (status === 409) return "لا يمكن تنفيذ الإجراء بسبب تعارض في البيانات.";
  if (status === 422) return "توجد بيانات ناقصة أو غير صحيحة.";
  if (status >= 500) {
    if (isUploadContext) return "تعذر رفع الملف. حاول مرة أخرى.";
    if (isProjectSubmitContext) return "تعذر حفظ التسليم. حاول مرة أخرى.";
    return "واجه الخادم مشكلة أثناء معالجة الطلب.";
  }

  return `تعذّر ${context}. حاول مرة أخرى بعد قليل.`;
};

const simplifyStudentMessage = (
  value: any,
  tone: "success" | "error" | "info" = "info",
) => {
  const text = String(value || "")
    .replace(/\s+/g, " ")
    .trim();
  if (!text) return "";
  const has = (...parts: string[]) =>
    parts.every((part) => text.includes(part));
  const any = (...parts: string[]) => parts.some((part) => text.includes(part));

  if (
    any(
      "تم تسجيل تسليم المشروع",
      "تم تسليم ملف مخرج مشروعك",
      "تم تسليم المشروع",
    )
  )
    return "تم تسليم المشروع بنجاح";
  if (any("تعذر حفظ التسليم"))
    return "تعذر حفظ التسليم. لم يصل العمل للأستاذ، حاول مرة أخرى.";
  if (has("المشروع", "تعذر")) return "تعذر تسليم المشروع. حاول مرة أخرى.";
  if (has("المشروع", "خطأ")) return "تعذر تسليم المشروع. حاول مرة أخرى.";
  if (any("تم تشغيل محرك التخصيص", "توليد مسودة مشروعك"))
    return "تم تجهيز المشروع";
  if (any("محرك التوليد", "فشل توليد")) return "تعذر تجهيز المشروع";

  if (any("تم تسليم الاختبار بنجاح", "تم تسليم الاختبار."))
    return "تم تسليم الاختبار";
  if (any("انتهى وقت الاختبار", "أغلق الوقت")) return "انتهى وقت الاختبار";
  if (has("تعذر", "تسليم الاختبار")) return "تعذر تسليم الاختبار";
  if (has("فشل", "الاختبار")) return "تعذر تسليم الاختبار";
  if (any("تم تسجيل إجابتك للتمرين", "تم تسليم النشاط"))
    return "تم تسليم النشاط";
  if (has("تعذر", "تسليم النشاط")) return "تعذر تسليم النشاط";
  if (has("درجات", "التمارين")) return "تعذر تسليم النشاط";

  // رسالة منع إنشاء اختبار بلا بنك أسئلة: نُبقيها قصيرة وواضحة بدل تحويلها إلى
  // سقوط عام يخفي السبب.
  if (
    any("بنك الأسئلة", "بنك أسئلة") &&
    any("أضف", "لا يوجد", "أولاً", "تصنيف")
  )
    return "أضف أسئلة لبنك الأسئلة أولاً قبل إنشاء الاختبار.";

  if (any("تم فتح المقرر", "تم تفعيل المقرر")) return "تم تفعيل المقرر";
  if (
    any(
      "تهانينا! تم التحقق",
      "تم حساب بصمة التعلم",
      "تم بنجاح فتح خدمات المختبر",
    )
  )
    return "تم تفعيل الحساب";
  if (
    any(
      "الكود غير صحيح",
      "الكود منتهي",
      "الكود مستخدم",
      "الكود موقوف",
      "الكود لم يبدأ",
      "الطالب غير موجود في كشوفات",
      "الطالب غير موجود في كشف",
      "تعذر تحميل بيانات الطالب بعد التفعيل",
      "رد الخادم لم يحتوِ بيانات الطالب كاملة",
      "تعذر الاتصال بالخادم. تحقق من الشبكة",
    )
  )
    return text;
  if (
    any(
      "رمز المقرر الأكاديمي لا يتوافق",
      "تعذر تفعيل المقرر",
      "رمز التحقق غير صحيح",
      "رمز الانضمام غير صالح",
      "بيانات الدخول غير صحيحة",
      "خطأ في بيانات الدخول",
    )
  )
    return "البيانات غير صحيحة";
  if (any("اكتب كود تفعيل", "يرجى إدخال رمز الانضمام", "أدخل رمز الانضمام"))
    return "اكتب رمز المقرر";
  if (any("الرجاء إدخال كود المختبر")) return "اكتب رمز المقرر";

  if (any("تم الدخول بالبصمة", "تم فتح جلسة SEB", "أهلاً بك مجدداً", "مرحباً"))
    return "تم الدخول بنجاح";
  if (any("تم تفعيل الدخول بالبصمة")) return "تم تفعيل البصمة";
  if (any("هذا الجهاز لا يدعم الدخول بالبصمة")) return "البصمة غير مدعومة";
  if (any("تعذر بدء تفعيل البصمة", "تعذر اعتماد البصمة"))
    return "تعذر تفعيل البصمة";
  if (any("تم إلغاء ثقة الجهاز")) return "تم إلغاء الجهاز";
  if (any("تعذر إلغاء ثقة الجهاز")) return "تعذر إلغاء الجهاز";

  if (any("تم تغيير كلمة المرور")) return "تم تغيير كلمة المرور";
  if (any("اكتب كلمة مرور جديدة")) return "اكتب كلمة مرور جديدة";
  if (any("كلمة المرور وتأكيدها غير متطابقين"))
    return "كلمتا المرور غير متطابقتين";
  if (any("رابط إعادة التعيين غير صالح")) return "الرابط غير صالح";
  if (any("نسيت كلمة المرور")) return "اكتب الرقم الجامعي";
  if (any("تم تسجيل طلب الاسترجاع")) return "تم إرسال الطلب";
  if (has("تعذر", "الاسترجاع")) return "تعذر إرسال الطلب";

  if (any("صيغة الملف", "نوع الملف", "غير مدعومة", "غير مسموحة"))
    return text.includes("الصيغ المتاحة")
      ? text
      : `صيغة الملف غير مدعومة. الصيغ المتاحة: ${MIRAS_ALLOWED_SUBMISSION_FORMATS_LABEL}.`;
  if (any("حجم الملف"))
    return text.includes("ميجابايت")
      ? text
      : "حجم الملف كبير. الحد الأقصى المسموح 25 ميجابايت.";
  if (any("الحد الأقصى لعدد الملفات")) return "الحد الأقصى 10 ملفات";
  if (any("تعذر رفع الملف", "فشل رفع الملف", "تعثر رفع الملف"))
    return "تعذر رفع الملف. تأكد من الإنترنت ثم حاول مرة أخرى.";
  if (any("ملف Excel فارغ")) return "الملف فارغ";
  if (any("تعذر قراءة ملف Excel", "تعذر قراءة الملف"))
    return "تعذر قراءة الملف";

  if (any("تم دفع الاشتراك")) return "تم تفعيل مِراس";
  if (any("KNET")) return "تعذر الدفع";
  if (any("تم اجتياز التدقيق")) return "تم التحقق";

  if (
    any(
      "جاري التحقق من ثبات الشاشة",
      "إبقاء الشاشة ثابتة",
      "قفل الشاشة",
      "الوضع الطولي",
      "الشاشة ثابتة",
    )
  )
    return "ثبّت الشاشة للمتابعة";
  if (any("مخالفة", "محاولة غش", "الغش", "أدوات المطور", "PrintScreen"))
    return "تم رصد مخالفة";
  if (any("انسحب الطالب")) return "تم تسجيل الانسحاب";

  if (any("جلسة SEB غير صالحة")) return "جلسة SEB غير صالحة";
  if (
    any(
      "تعذر إنشاء جلسة SEB",
      "تعذر تجهيز ملف SEB",
      "تعذر تحميل أسئلة الاختبار داخل SEB",
      "تعذر التحقق من جلسة SEB",
    )
  )
    return "تعذر تشغيل SEB";
  if (any("داخل Safe Exam Browser")) return "افتح الاختبار من حساب الطالب";
  if (any("يجب الدخول من الجهاز الأصلي")) return "ادخل من الجهاز الأصلي";
  if (
    any(
      "مرتبط بجهاز آخر",
      "جهازك الحالي مختلف",
      "جهاز مختلف عن جهاز التفعيل",
      "لا يمكن نقل نفس كود التفعيل",
    )
  ) {
    return "هذا الحساب يعمل على الجهاز الأصلي فقط. افتحه من جهاز التفعيل أو راجع أستاذ المقرر.";
  }

  if (
    any(
      "هذا الحساب مقفل",
      "عمل على الجهاز الأصلي",
      "هذا الحساب مسجل في جهاز آخر",
      "للتبديل لهذا الجهاز",
      "حسابك في وضع النقل",
      "تعذّر التعرف على جهازك",
      "تم إيقاف حسابك",
      "تعذر التحقق من الجهاز",
      "تم إنهاء جلسة",
      "راجع أستاذ المقرر",
      "الرمز البديل",
      "تبديل الجهاز",
      "جهازاً جديداً",
      "غير مدرج في كشف",
      "غير مطابق لكشف",
      "مخصص لطالب آخر",
      "الصادر باسمك",
      "البريد الإلكتروني",
      "الرقم الجامعي مسجل",
      "حساب مفعل مسبقًا",
      "أضف المقرر الجديد من داخل حسابك",
      "غير مكتمل",
      "كلمة المرور",
      "مرتبط بحساب طالب آخر",
      "جهاز مرتبط بحساب طالب آخر",
      "جهازك الشخصي",
      "مراجعة أستاذ المقرر",
    )
  ) {
    return text;
  }

  // رسائل النجاح التي تذكر QR/الكاميرا (مثل "تم التقاط كود التفعيل من QR
  // بنجاح.") يجب ألا تتحول أبداً إلى نص فشل "تعذر تشغيل الكاميرا" يُعرض كتوست
  // أخضر بعلامة صح. نتعامل مع تبسيط الكاميرا كحالة فشل فقط لغير نغمة النجاح.
  if (
    tone !== "success" &&
    any("الكاميرا", "QR", "BarcodeDetector", "Barcode Detector")
  ) {
    if (any("السماح", "إذن", "رفض", "permission", "NotAllowed"))
      return "اسمح للكاميرا ثم أعد المحاولة";
    if (any("غير مدعومة", "غير متاحة", "unsupported", "NotFound"))
      return "الكاميرا غير متاحة، اكتب الكود يدويًا";
    return "تعذر تشغيل الكاميرا";
  }

  if (
    any(
      "تعذر الاتصال بالخادم",
      "عطل في الاتصال",
      "الاتصال بالخادم",
      "انقطع الاتصال",
      "تعذر الاتصال",
    )
  )
    return "تعذر الاتصال. تأكد من الإنترنت ثم حاول مرة أخرى.";
  if (any("عطل", "خطأ ميكانيكي", "خطأ مستودع"))
    return extractApiErrorReason(text, "تنفيذ الإجراء");
  if (
    any(
      "رقم المقرر مستخدم",
      "اسم المقرر",
      "احذف المقرر القديم",
      "كود تفعيل",
      "غير موجود في كشف",
      "أنت غير موجود في كشف",
      "جلسة الأستاذ غير واضحة",
    )
  ) {
    return text;
  }
  if (text.length <= 42) return text;
  if (tone === "success") return "تمت العملية بنجاح";
  if (tone === "error") return extractApiErrorReason(text, "عرض الرسالة");
  return text.slice(0, 42).replace(/[،.؛:：\-–—\s]+$/, "");
};

const simplifyMirasMessage = (
  value: any,
  tone: "success" | "error" | "info" = "info",
) => {
  const text = String(value || "")
    .replace(/\s+/g, " ")
    .trim();
  if (!text) return "";
  const any = (...parts: string[]) => parts.some((part) => text.includes(part));
  if (
    /Failed to fetch|NetworkError|Load failed|fetch failed|TypeError: fetch|network|CORS/i.test(
      text,
    )
  )
    return "تعذر الاتصال بالخادم. تحقق من الاتصال بالإنترنت.";
  if (
    /صيغة الملف|نوع الملف|غير مدعوم|غير مسموح|حجم الملف|تعذر حفظ الملف|تعذر رفع الملف|تعذر تسليم المشروع|تعذر حفظ المرفقات/i.test(
      text,
    )
  ) {
    return simplifyStudentMessage(text, tone);
  }
  if (/Firebase|Firestore|Quota|quota|database/i.test(text)) {
    if (tone === "success") return "تم الحفظ";
    return "الخدمة مشغولة مؤقتًا";
  }
  if (
    /تعذر تشغيل الكاميرا|تعذّر تشغيل الكاميرا|camera-video-not-ready|NotReadable|TrackStart|Overconstrained|AbortError|Could not start video source|camera-unavailable|BarcodeDetector/i.test(
      text,
    )
  )
    return "العدسة تحتاج محاولة ثانية";
  if (any("خطأ ميكانيكي", "خطأ مستودع", "خطأ غير معروف"))
    return extractApiErrorReason(text, "تنفيذ الإجراء");

  // Miras copy system: كل رسائل المعلم والطالب تظهر كإشارات قصيرة جداً.
  // لا نغيّر المنطق أو البيانات؛ فقط نختصر نصوص التوست/التنبيه/الحوار.
  const t = text;
  if (/^(https?:\/\/|www\.)/i.test(t) || /^[A-Z0-9]{4,}[-_A-Z0-9]*$/i.test(t)) return t;

  if (tone === "success") {
    if (any("نسخ", "clipboard")) return "تم النسخ";
    if (any("تصدير", "Excel", "PDF", "المطبعة")) return "تم التصدير";
    if (any("استيراد", "قراءة ملف Excel", "رفع كشف")) return "تم الاستيراد";
    if (any("حفظ", "اعتماد", "نشر")) return any("درجة", "درجات") ? "تم رصد الدرجات" : "تم الحفظ";
    if (any("حذف", "إزالة")) return "تم الحذف";
    if (any("تعديل", "تحديث", "تغيير")) return "تم التحديث";
    if (any("إضافة", "أُضيف", "اضافة")) return "تمت الإضافة";
    if (any("إنشاء", "انشاء", "تجهيز", "توليد")) return any("كود", "رمز") ? "تم توليد الكود" : "تم التجهيز";
    if (any("تفعيل", "فتح المقرر", "فتح الحساب")) return "تم التفعيل";
    if (any("رصد", "درجة", "درجات")) return "تم رصد الدرجات";
    if (any("رفع", "تسليم")) return any("اختبار") ? "تم تسليم الاختبار" : any("مشروع") ? "تم تسليم المشروع" : "تم التسليم";
    if (any("إرسال", "تنبيه")) return "تم الإرسال";
    if (any("تنظيف")) return "تم التنظيف";
    if (t.length > 28) return "تم";
  }

  if (tone === "error") {
    if (any("اكتب", "أدخل", "يرجى إدخال", "اختر", "حدد")) {
      if (any("درجة")) return "اكتب الدرجة";
      if (any("طالب", "طلبة")) return "اختر الطالب";
      if (any("مقرر")) return "اختر المقرر";
      if (any("عنوان")) return "اكتب العنوان";
      if (any("كلمة مرور")) return "اكتب كلمة المرور";
      return "أكمل البيانات";
    }
    if (any("لا توجد", "لم يتم العثور", "لم أجد")) {
      if (any("رموز", "أكواد")) return "لا توجد أكواد";
      if (any("تسليم")) return "لا توجد تسليمات";
      if (any("أسئلة")) return "لا توجد أسئلة";
      if (any("طالب", "طلبة")) return "لا يوجد طالب";
      return "لا توجد بيانات";
    }
    if (any("تعذر", "تعذّر", "فشل", "عطل")) {
      if (any("الاتصال", "الخادم", "الشبكة")) return "تعذر الاتصال";
      if (any("تصدير", "PDF", "المطبعة")) return "تعذر التصدير";
      if (any("استيراد", "قراءة")) return "تعذر الاستيراد";
      if (any("حفظ", "اعتماد", "نشر", "تحديث")) return "تعذر الحفظ";
      if (any("حذف", "إزالة")) return "تعذر الحذف";
      if (any("توليد", "إنشاء", "تجهيز")) return "تعذر التجهيز";
      if (any("تفعيل", "فتح المقرر")) return "تعذر التفعيل";
      if (any("رفع", "ملف")) return "تعذر الرفع";
      if (any("تحميل")) return "تعذر التحميل";
      if (any("تسليم")) return "تعذر التسليم";
      if (any("كلمة المرور", "استرجاع")) return "تعذر الاسترجاع";
      return "تعذر التنفيذ";
    }
    if (t.length > 34) return extractApiErrorReason(t, "تنفيذ الإجراء").slice(0, 34).replace(/[،.؛:：\-–—\s]+$/, "");
  }

  const simplified = simplifyStudentMessage(text, tone);
  if (simplified.length > 34) {
    if (tone === "success") return "تم";
    if (tone === "error") return extractApiErrorReason(simplified, "تنفيذ الإجراء").slice(0, 34).replace(/[،.؛:：\-–—\s]+$/, "");
    return simplified.slice(0, 34).replace(/[،.؛:：\-–—\s]+$/, "");
  }
  return simplified;
};

const compactMirasDialogMessage = (
  value: any,
  type: "confirm" | "prompt" = "confirm",
) => {
  const text = String(value || "").replace(/\s+/g, " ").trim();
  if (!text) return type === "prompt" ? "اكتب المطلوب" : "هل أنت متأكد؟";
  if (type === "prompt") {
    if (/الرقم الجامعي/.test(text)) return "الرقم الجامعي";
    if (/كلمة المرور/.test(text)) return "كلمة المرور";
    if (/رمز|كود/.test(text)) return "الكود";
    if (/اسم/.test(text)) return "الاسم";
    return text.length > 28 ? "اكتب المطلوب" : text;
  }
  if (/حذف/.test(text)) {
    if (/طالب/.test(text)) return "حذف الطالب؟";
    if (/مشروع/.test(text)) return "حذف المشروع؟";
    if (/اختبار/.test(text)) return "حذف الاختبار؟";
    if (/سؤال/.test(text)) return "حذف السؤال؟";
    if (/مقرر/.test(text)) return "حذف المقرر؟";
    if (/رمز|كود/.test(text)) return "حذف الكود؟";
    if (/استرجاع/.test(text)) return "حذف الطلب؟";
    return "حذف؟";
  }
  if (/إيقاف|تعطيل/.test(text)) return "إيقاف الحساب؟";
  if (/إعادة تفعيل|تفعيل/.test(text)) return "تفعيل الحساب؟";
  if (/تغيير حالة|حالة/.test(text)) return "تغيير الحالة؟";
  if (/رمز بديل|بديل/.test(text)) return "إصدار رمز بديل؟";
  if (/درجة|درجات|رصد/.test(text)) return "اعتماد الدرجات؟";
  if (/استيراد/.test(text)) return "استيراد البيانات؟";
  if (/تصدير/.test(text)) return "تصدير البيانات؟";
  if (text.length <= 30) return text;
  return simplifyMirasMessage(text, "info");
};

const allowedRosterRowsToText = (rows: any[]) =>
  rows
    .map(
      (row) =>
        `${String(row.idNumber || "").trim()}, ${String(row.name || "").trim()}, ${String(row.sectionCode || "").trim()}`,
    )
    .filter((line) => !line.startsWith(",") && !line.includes(", ,"))
    .join("\n");
const isLiveRecord = (item: any) =>
  item &&
  item.deleted !== true &&
  item.archived !== true &&
  item.isDeleted !== true &&
  item.isArchived !== true &&
  item.active !== false &&
  item.isActive !== false &&
  String(item.status || "").toLowerCase() !== "deleted";

const isArchivedJoinCodeRecord = (item: any) => {
  if (!item) return true;
  const status = String(item.status || "")
    .trim()
    .toLowerCase();
  return Boolean(
    item.archived === true ||
    item.isArchived === true ||
    item.archivedAt ||
    item.retiredAt ||
    item.retiredReason ||
    status === "retired" ||
    status === "archived" ||
    status === "archive" ||
    status === "deleted",
  );
};

const isLiveJoinCodeRecord = (item: any) =>
  isLiveRecord(item) && !isArchivedJoinCodeRecord(item);

const isRecentlyIssuedJoinCodeRecord = (
  item: any,
  windowMs = 10 * 60 * 1000,
) => {
  const created = new Date(item?.createdAt || item?.issuedAt || 0).getTime();
  return (
    Number.isFinite(created) && created > 0 && Date.now() - created < windowMs
  );
};

type MirasPasskeyRole = "teacher" | "student" | "admin";
type MirasPasskeyLocalLock = {
  role: MirasPasskeyRole;
  userId: string;
  userName?: string;
  enabledAt?: string;
};
const MIRAS_PASSKEY_LOCAL_LOCK_KEY = "miras_passkey_local_lock_v1";
const MIRAS_PASSKEY_BACKGROUND_AT_KEY = "miras_passkey_background_at_v1";
// مدة بقاء الجلسة مفتوحة بعد الخلفية قبل طلب البصمة من جديد. كانت 30 ثانية (فتطلب
// البصمة في كل فتح تقريباً). بما أن الحساب مقفول على جهاز واحد، نمدّدها إلى 12 ساعة
// ليفتح التطبيق مباشرة على لوحة الطالب/المعلم دون ضغط أي زر طوال اليوم. تُطلب البصمة
// مرة واحدة فقط بعد غياب طويل (بداية باردة).
const MIRAS_PASSKEY_SMART_LOCK_MS = 12 * 60 * 60 * 1000;
const normalizeMirasPasskeyIdentity = (role: any, userId: any) => {
  const id = String(userId || "").trim();
  return role === "teacher" || role === "admin" ? id.toLowerCase() : id;
};
const readMirasPasskeyLocalLock = (): MirasPasskeyLocalLock | null => {
  try {
    const raw = localStorage.getItem(MIRAS_PASSKEY_LOCAL_LOCK_KEY);
    if (!raw) return null;
    const parsed = JSON.parse(raw);
    if (
      parsed?.role !== "teacher" &&
      parsed?.role !== "student" &&
      parsed?.role !== "admin"
    )
      return null;
    if (!parsed?.userId) return null;
    return {
      ...parsed,
      userId: normalizeMirasPasskeyIdentity(parsed.role, parsed.userId),
    };
  } catch {
    return null;
  }
};
const writeMirasPasskeyLocalLock = (
  role: MirasPasskeyRole,
  userId: any,
  userName?: any,
) => {
  try {
    const lock: MirasPasskeyLocalLock = {
      role,
      userId: normalizeMirasPasskeyIdentity(role, userId),
      userName: String(userName || "").trim() || undefined,
      enabledAt: new Date().toISOString(),
    };
    localStorage.setItem(MIRAS_PASSKEY_LOCAL_LOCK_KEY, JSON.stringify(lock));
    return lock;
  } catch {
    return null;
  }
};
const sessionIdentityForPasskey = (role: MirasPasskeyRole, session: any) =>
  role === "teacher" || role === "admin"
    ? normalizeMirasPasskeyIdentity(role, session?.email || session?.id)
    : normalizeMirasPasskeyIdentity(role, session?.id || session?.email);
const passkeyLockMatchesSession = (role: MirasPasskeyRole, session: any) => {
  const lock = readMirasPasskeyLocalLock();
  if (!lock || !session) return false;
  const isLockInstructor = lock.role === "teacher" || lock.role === "admin";
  const isRoleInstructor = role === "teacher" || role === "admin";
  if (isLockInstructor !== isRoleInstructor) return false;
  return lock.userId === sessionIdentityForPasskey(role, session);
};
const storedSessionNeedsPasskeyUnlock = () => {
  const lock = readMirasPasskeyLocalLock();
  if (!lock) return false;
  try {
    if (lock.role === "student") {
      const raw = localStorage.getItem("miras_student_session");
      const session = raw ? JSON.parse(raw) : null;
      return (
        !!session &&
        lock.userId === sessionIdentityForPasskey("student", session)
      );
    }
    const raw = localStorage.getItem("miras_teacher_session");
    const session = raw ? JSON.parse(raw) : null;
    const sessionRole = session?.role === "admin" ? "admin" : "teacher";
    return (
      !!session &&
      lock.userId === sessionIdentityForPasskey(sessionRole, session)
    );
  } catch {
    return false;
  }
};

const mergeRosterRowsById = (...groups: any[][]) => {
  const map = new Map<string, any>();
  groups.flat().forEach((row: any) => {
    const idNumber = String(
      row?.idNumber || row?.studentId || row?.id || "",
    ).trim();
    const name = String(row?.name || row?.studentName || "").trim();
    const sectionCode = String(
      row?.sectionCode || row?.studentSection || "TECH-A1",
    ).trim();
    if (!idNumber || !name) return;
    const key = `${idNumber}::${sectionCode.toLowerCase()}`;
    map.set(key, {
      ...map.get(key),
      ...row,
      idNumber,
      id: idNumber,
      name,
      sectionCode,
    });
  });
  return Array.from(map.values());
};

const MIRAS_SEB_CONFIG_NAME = "miras-official.seb";
const MIRAS_SEB_CONFIG_PATH = "/seb/miras-official.seb";
// يجب أن تطابق هاتان القيمتان EXAM_IN_PROGRESS_STATUS و
