// نغمة لون ناعمة لبطاقات تنبيهات الطالب — تُشتق من نص الحالة/العنوان حتى
// تظهر التنبيهات منسّقة بألوان دلالية هادئة بدل لون واحد موحّد.
// نغمة لونية دلالية لبطاقات تنبيهات الطالب: معاد→كهرماني، درجة/تسليم→أخضر،
// إلغاء/غش/مغلق→وردي، والباقي→نيلي هادئ. تُرجِع مفتاح النغمة فقط.
type StudentNoticeToneKey =
  "emerald" | "amber" | "rose" | "indigo" | "violet" | "sky";
const studentNoticeTone = (text: string): StudentNoticeToneKey => {
  const t = String(text || "");
  if (/كلمة\s*مرور|استرجاع|إعادة\s*تعيين|نسيت/.test(t)) return "violet";
  if (/معاد|أعيد|إرجاع|إعادة|متاحة من جديد|مفتوحة من جديد/.test(t))
    return "amber";
  if (
    /درجة معتمدة|درجة مرصودة|مرصودة|معتمدة|رصد الدرجة|تم التسليم|تم الرصد|تم الإرسال|مكتمل|تم الاعتماد|تم تسليم|تم التفعيل|تفعيل ناجح|ناجح|قبول|مقبول/.test(
      t,
    )
  )
    return "emerald";
  if (
    /انتهى|مغلق|أُغلق|إلغاء|حذف|غش|انقطع|تعذّر|تعذر|رفض|مرفوض|محاولة غش|شبهة|تحذير|مخالفة|انتهاك/.test(
      t,
    )
  )
    return "rose";
  if (/تنبيه|إشعار|معلومة|تذكير|قريب|قريباً/.test(t)) return "sky";
  return "indigo";
};

