// يختصر نص التنبيه الطويل إلى صيغة بسيطة ومريحة: العنوان + التاريخ فقط،
// مع إسقاط الأجزاء الوصفية المكررة (الفئة/الرمز/الحالة) لأن الحالة تظهر
// أصلاً من لون البطاقة. بدون تعقيد وبلا قصّ في منتصف الكلمة.
const SHORT_NOTICE_DASH = /\s[–—-]\s/;
const SHORT_NOTICE_DATE =
  /[0-9٠-٩]{1,4}[\/.\-][0-9٠-٩]{1,2}(?:[\/.\-][0-9٠-٩]{2,4})?/;
const shortStudentNotice = (raw: string): string => {
  const cleaned = String(raw || "")
    .replace(/\s+/g, " ")
    .trim()
    .replace(/^(اختبار|مشروع|واجب|تنبيه)[:：]?\s*/, "")
    .trim();
  if (!cleaned) return "";
  const parts = cleaned
    .split(SHORT_NOTICE_DASH)
    .map((s) => s.trim())
    .filter(Boolean);
  if (parts.length <= 1) {
    return cleaned;
  }
  let title = parts[0];
  const datePart = parts.find(
    (p) => p !== parts[0] && SHORT_NOTICE_DATE.test(p),
  );
  const remainingParts = parts.filter((p) => p !== parts[0] && p !== datePart);
  const body = remainingParts.join(" — ");

  if (datePart && body) return `${title} — ${body} · ${datePart}`;
  if (datePart) return `${title} · ${datePart}`;
  if (body) return `${title} — ${body}`;
  return title;
};

const NORMAL_EXAM_MIN_WIDTH = 360;
const NORMAL_EXAM_MIN_HEIGHT = 520;
const NORMAL_EXAM_MIN_SCREEN_COVERAGE = 0.86;
const NORMAL_EXAM_STABLE_START_MS = 3000;
const NORMAL_EXAM_LANDSCAPE_RECOVERY_MS = 6500;
const NORMAL_EXAM_ORIENTATION_EVENT_GRACE_MS = 4500;
const NORMAL_EXAM_STABLE_SAMPLE_MS = 250;
const NORMAL_EXAM_MOBILE_VISUAL_OFFSET_TOLERANCE = 64;
const NORMAL_EXAM_ACTIVE_SCROLL_TOLERANCE = 1;
const sleep = (ms: number) =>
  new Promise((resolve) => window.setTimeout(resolve, ms));
const getNormalExamViewportIssue = (strictActiveExamScroll = false) => {
  if (typeof window === "undefined" || typeof document === "undefined")
    return "";
  const visualViewport = window.visualViewport;
  const viewportOffsetTop = Math.round(visualViewport?.offsetTop || 0);
  const viewportWidth = Math.round(
    visualViewport?.width ||
      window.innerWidth ||
      document.documentElement.clientWidth ||
      0,
  );
  const viewportHeight = Math.round(
    visualViewport?.height ||
      window.innerHeight ||
      document.documentElement.clientHeight ||
      0,
  );
  const pageScrollY = Math.round(
    Math.max(
      window.scrollY || 0,
      document.documentElement?.scrollTop || 0,
      document.body?.scrollTop || 0,
    ),
  );
  const screenWidth = Math.round(
    window.screen?.width || window.screen?.availWidth || viewportWidth || 0,
  );
  const screenHeight = Math.round(
    window.screen?.height || window.screen?.availHeight || viewportHeight || 0,
  );
  const availableWidth = Math.round(
    window.screen?.availWidth || screenWidth || viewportWidth || 0,
  );
  const availableHeight = Math.round(
    window.screen?.availHeight || screenHeight || viewportHeight || 0,
  );
  const expectedWidth = Math.max(screenWidth, availableWidth, viewportWidth);
  const expectedHeight = Math.max(
    screenHeight,
    availableHeight,
    viewportHeight,
  );
  const widthCoverage = expectedWidth > 0 ? viewportWidth / expectedWidth : 1;
  const heightCoverage =
    expectedHeight > 0 ? viewportHeight / expectedHeight : 1;
  const isLandscape = viewportWidth > viewportHeight;
  const isMobileLikeViewport =
    Math.min(screenWidth, screenHeight) <= 700 ||
    (typeof navigator !== "undefined" &&
      /Android|iPhone|iPad|iPod|Mobile/i.test(navigator.userAgent || "")) ||
    (typeof window.matchMedia === "function" &&
      window.matchMedia("(pointer: coarse)").matches);

  if (document.hidden || (!document.hasFocus() && !isMobileLikeViewport))
    return "يرجى فتح الاختبار بكامل الشاشة قبل البدء.";
  // قبل بدء الاختبار نسمح بهامش جوال صغير كي لا يمنع شريط المتصفح فتح الاختبار.
  // بعد ظهور الأسئلة يصبح الاختبار العادي صارماً: أي رفع/سحب فعلي للصفحة أو
  // إزاحة للـ visualViewport ولو بسيطاً يُعامل كمغادرة لوضع الاختبار الآمن.
  if (strictActiveExamScroll) {
    if (pageScrollY > NORMAL_EXAM_ACTIVE_SCROLL_TOLERANCE)
      return "تم رصد رفع شاشة الاختبار أو تحريكها خارج الوضع الآمن.";
    if (viewportOffsetTop > NORMAL_EXAM_ACTIVE_SCROLL_TOLERANCE)
      return "تم رصد رفع شاشة الاختبار أو تحريكها خارج الوضع الآمن.";
  } else {
    const visualOffsetTolerance = isMobileLikeViewport
      ? NORMAL_EXAM_MOBILE_VISUAL_OFFSET_TOLERANCE
      : 8;
    if (viewportOffsetTop > visualOffsetTolerance)
      return "تم رصد رفع شاشة الاختبار أو تحريكها خارج الوضع الآمن.";
  }
  if (isLandscape)
    return "يرجى تدوير الجهاز للوضع الطولي قبل بدء الاختبار؛ الاختبار العادي لا يعمل بالعرض.";
  if (
    viewportWidth < NORMAL_EXAM_MIN_WIDTH ||
    viewportHeight < NORMAL_EXAM_MIN_HEIGHT
  )
    return "يرجى فتح الاختبار بكامل الشاشة قبل البدء.";
  const largeScreenWindowed =
    !isMobileLikeViewport && (expectedWidth >= 700 || expectedHeight >= 700);
  const crampedWindow =
    largeScreenWindowed &&
    (widthCoverage < NORMAL_EXAM_MIN_SCREEN_COVERAGE || heightCoverage < 0.94);
  const tabletOrLargeTouchViewport =
    isMobileLikeViewport && Math.min(screenWidth, screenHeight) >= 700;
  const mobileSplitViewOrFloatingWindow = tabletOrLargeTouchViewport
    ? widthCoverage < 0.82 || heightCoverage < 0.72
    : widthCoverage < 0.68 || heightCoverage < 0.52;
  if (crampedWindow || mobileSplitViewOrFloatingWindow)
    return "يرجى فتح الاختبار بكامل الشاشة قبل البدء.";
  return "";
};
const getNormalExamViewportSignature = () => {
  if (typeof window === "undefined" || typeof document === "undefined")
    return "";
  const visual = window.visualViewport;
  const w = Math.round(visual?.width || window.innerWidth || 0);
  const h = Math.round(visual?.height || window.innerHeight || 0);
  return `${Math.round(w / 8) * 8}x${Math.round(h / 8) * 8}:${document.visibilityState}:${document.hasFocus() ? "focus" : "blur"}`;
};

// قارئ QR احتياطي شامل: يحمَّل ديناميكياً مرة واحدة عند الحاجة من CDN.
// السبب: BarcodeDetector غير متاح على iOS Safari ولا Firefox، فبدون قارئ
// احتياطي يفشل المسح/الصورة عند معظم الطلبة. هذا التحميل lazy: لا يؤثر
// على حجم الـ bundle ولا على صفحات لا تستخدم العدسة.
const MIRAS_JSQR_CDN_URL =
  "https://cdn.jsdelivr.net/npm/jsqr@1.4.0/dist/jsQR.min.js";
let mirasJsQrLoadingPromise: Promise<any> | null = null;
const ensureMirasJsQrReader = (): Promise<any> => {
  if (typeof window === "undefined") return Promise.resolve(null);
  const w = window as any;
  if (typeof w.jsQR === "function") return Promise.resolve(w.jsQR);
  if (mirasJsQrLoadingPromise) return mirasJsQrLoadingPromise;
  mirasJsQrLoadingPromise = new Promise((resolve) => {
    try {
      const existing = document.querySelector<HTMLScriptElement>(
        'script[data-miras-jsqr="1"]',
      );
      const finalize = () => resolve((window as any).jsQR || null);
      if (existing) {
        if ((window as any).jsQR) return finalize();
        existing.addEventListener("load", finalize, { once: true });
        existing.addEventListener(
          "error",
          () => {
            mirasJsQrLoadingPromise = null;
            resolve(null);
          },
          { once: true },
        );
        return;
      }
      const script = document.createElement("script");
      script.src = MIRAS_JSQR_CDN_URL;
      script.async = true;
      script.crossOrigin = "anonymous";
      script.setAttribute("data-miras-jsqr", "1");
      script.onload = finalize;
      script.onerror = () => {
        mirasJsQrLoadingPromise = null;
        try {
          script.remove();
        } catch {}
        resolve(null);
      };
      document.head.appendChild(script);
    } catch {
      mirasJsQrLoadingPromise = null;
      resolve(null);
    }
  });
  return mirasJsQrLoadingPromise;
};

// فك ترميز QR من مصدر صورة (فيديو/Bitmap/Image) عبر Canvas — يعمل على كل متصفح.
// نجرّب 3 نوافذ بالترتيب: قص مركزي ضيق (75%) → قص مركزي متوسط (90%) → كامل
// الإطار. هذا يلتقط الكود حتى وهو صغير في المنتصف دون الحاجة لتحريك الكاميرا
// يميناً ويساراً — وهي شكوى متكررة على شاشة الجوال.
const decodeQrWithMirasJsQr = async (
  source: CanvasImageSource | ImageBitmap | HTMLVideoElement | HTMLImageElement,
): Promise<string> => {
  const jsQR = await ensureMirasJsQrReader();
  if (!jsQR) return "";
  try {
    let width = 0;
    let height = 0;
    if ((source as HTMLVideoElement).videoWidth) {
      width = (source as HTMLVideoElement).videoWidth;
      height = (source as HTMLVideoElement).videoHeight;
    } else if ((source as HTMLImageElement).naturalWidth) {
      width = (source as HTMLImageElement).naturalWidth;
      height = (source as HTMLImageElement).naturalHeight;
    } else if ((source as ImageBitmap).width) {
      width = (source as ImageBitmap).width;
      height = (source as ImageBitmap).height;
    }
    if (!width || !height) return "";

    const canvas = document.createElement("canvas");
    const ctx = canvas.getContext("2d", {
      willReadFrequently: true,
    } as any) as CanvasRenderingContext2D | null;
    if (!ctx) return "";

    const isLiveVideo = !!(source as HTMLVideoElement).videoWidth;
    // للفيديو الحي: نرفع الدقة إلى 1024px (بدل 720) لتفاصيل أعلى، ومع كل
    // محاولة نقصّ نافذة مركزية أصغر فيُكبَّر الكود نسبياً ويلتقطه jsQR.
    const targetSize = isLiveVideo
      ? 1024
      : Math.min(1280, Math.max(width, height));
    const cropRatios = isLiveVideo ? [0.7, 0.9, 1] : [1, 0.85];

    for (const ratio of cropRatios) {
      const cropSide = Math.floor(Math.min(width, height) * ratio);
      const sx = Math.floor((width - cropSide) / 2);
      const sy = Math.floor((height - cropSide) / 2);
      const drawSide = Math.min(targetSize, cropSide);
      canvas.width = drawSide;
      canvas.height = drawSide;
      ctx.drawImage(
        source as any,
        sx,
        sy,
        cropSide,
        cropSide,
        0,
        0,
        drawSide,
        drawSide,
      );
      const img = ctx.getImageData(0, 0, drawSide, drawSide);
      const result = jsQR(img.data, img.width, img.height, {
        inversionAttempts: "attemptBoth",
      });
      if (result && result.data) return result.data;
    }
    return "";
  } catch {
    return "";
  }
};
const isSafeExamBrowserSession = () => {
  if (typeof navigator === "undefined") return false;
  try {
    const params = new URLSearchParams(window.location.search);
    const sebPass = params.get("seb_token") || params.get("seb_pass");
    const sebExamId = params.get("exam_id");
    const sebCourse = params.get("course");
    if (sebPass) sessionStorage.setItem("mirasSebPass", sebPass);
    if (sebExamId) sessionStorage.setItem("mirasSebExamId", sebExamId);
    if (sebCourse) sessionStorage.setItem("mirasSebCourseCode", sebCourse);
    if (params.get("seb") === "1" || params.get("miras_seb") === "1") {
      sessionStorage.setItem("mirasSebSession", "1");
      return true;
    }
    if (sessionStorage.getItem("mirasSebSession") === "1") return true;
  } catch {}
  return /SafeExamBrowser|SEB/i.test(navigator.userAgent);
};
const isActualSafeExamBrowserRuntime = () => {
  // Important: URL/session markers mean "SEB attempt context" only. They do NOT prove the
  // current browser is actually Safe Exam Browser. Normal browsers may keep these markers after
  // a failed launch, and treating them as real SEB hides the launch button and sends the student
  // into quiz generation without an active SEB runtime.
  if (typeof navigator === "undefined") return false;
  return /SafeExamBrowser|SEB/i.test(navigator.userAgent);
};
const getMirasSebPass = () => {
  try {
    const params = new URLSearchParams(window.location.search);
    const pass =
      params.get("seb_token") ||
      params.get("seb_pass") ||
      sessionStorage.getItem("mirasSebPass") ||
      "";
    if (pass) sessionStorage.setItem("mirasSebPass", pass);
    return pass;
  } catch {
    return "";
  }
};
const hasMirasSebAttemptContext = () => {
  if (typeof window === "undefined") return false;
  try {
    const params = new URLSearchParams(window.location.search);
    if (params.get("miras_seb") === "1" || params.get("seb") === "1")
      return true;
    if (sessionStorage.getItem("mirasSebSession") === "1") return true;
    if (sessionStorage.getItem("mirasSebSessionInfo")) return true;
  } catch {}
  return isSafeExamBrowserSession();
};
const buildMirasSebQuitPath = (token?: string) =>
  `/seb/quit?token=${encodeURIComponent(token || getMirasSebPass() || "")}`;
const clearMirasSebClientSession = () => {
  try {
    [
      "mirasSebPass",
      "mirasSebExamId",
      "mirasSebCourseCode",
      "mirasSebSession",
      "mirasSebSessionInfo",
      "mirasSebLaunchInfo",
      "mirasSebLaunchPending",
    ].forEach((key) => {
      sessionStorage.removeItem(key);
      localStorage.removeItem(key);
    });
  } catch {}
};
const isAppleMobileDevice = () => {
  if (typeof navigator === "undefined") return false;
  return (
    /iPad|iPhone|iPod/i.test(navigator.userAgent) ||
    (navigator.platform === "MacIntel" && (navigator as any).maxTouchPoints > 1)
  );
};
const toSebConfigDeepLink = (url: string) => {
  try {
    const absolute = new URL(url, window.location.origin).toString();
    // SEB expects sebs:// for HTTPS configuration links and seb:// for HTTP.
    if (/^https:\/\//i.test(absolute))
      return absolute.replace(/^https:\/\//i, "sebs://");
    if (/^http:\/\//i.test(absolute))
      return absolute.replace(/^http:\/\//i, "seb://");
    return absolute;
  } catch {
    return url;
  }
};
const cleanCodeForDisplay = (code: string) => {
  if (!code) return "";
  const c = String(code).trim();
  const upper = c.toUpperCase();
  if (upper === "TECH-A1" || upper === "TECH-B2" || upper === "EDU-2026")
    return c;
  // Teacher-scoped section ids may be stored as code-email or email-code.
  // Never show the email part to students/teachers; display the actual course code only.
  if (c.includes("@") && c.includes("-")) {
    const parts = c
      .split("-")
      .map((part) => part.trim())
      .filter(Boolean);
    const first = parts[0] || "";
    const last = parts[parts.length - 1] || "";
    if (/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(first)) return last;
    if (/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(last))
      return parts.slice(0, -1).join("-") || "";
    return last || first;
  }
  if (/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(c)) return "";
  return c;
};
const formatGradeFraction = (grade: any, total?: any) => {
  const normalizeDigits = (value: any) =>
    String(value ?? "")
      .replace(/[٠-٩]/g, (d) => String("٠١٢٣٤٥٦٧٨٩".indexOf(d)))
      .replace(/[۰-۹]/g, (d) => String("۰۱۲۳۴۵۶۷۸۹".indexOf(d)));
  const g = normalizeDigits(grade).trim();
  const t = normalizeDigits(total).trim();
  if (!g) return "";
  const text = t && t !== "-" ? `${g}/${t}` : g;
  return `\u202A${text}\u202C`;
};
const submitSebIosOpenForm = (payload: Record<string, any>) => {
  const form = document.createElement("form");
  form.method = "POST";
  form.action = "/seb/open";
  form.acceptCharset = "UTF-8";
  form.style.display = "none";
  Object.entries(payload).forEach(([key, value]) => {
    const input = document.createElement("input");
    input.type = "hidden";
    input.name = key;
    input.value = String(value ?? "");
    form.appendChild(input);
  });
  document.body.appendChild(form);
  form.submit();
};
const downloadSebConfigFile = (url: string, fileName?: string) => {
  const anchor = document.createElement("a");
  anchor.href = url || MIRAS_SEB_CONFIG_PATH;
  anchor.download = fileName || MIRAS_SEB_CONFIG_NAME;
  anchor.rel = "noopener";
  document.body.appendChild(anchor);
  anchor.click();
  anchor.remove();
};

const ONBOARDING_VERSION = "v2";
const onboardingStorageKey = (role: "teacher" | "student", id: any) =>
  `miras_onboarding_${role}_${ONBOARDING_VERSION}:${String(id || "guest")
    .trim()
    .toLowerCase()}`;
const isOnboardingDone = (key: string) => {
  if (!key || typeof window === "undefined") return true;
  try {
    return localStorage.getItem(key) === "done";
  } catch {
    return false;
  }
};

