  const [secondaryToolsOpen, setSecondaryToolsOpen] = useState(false);
  // انكماش الشريط السفلي (Dock) كان مخزَّناً كـ React state، فكل تبديل له أثناء
  // التمرير كان يعيد رسم شجرة الواجهة العملاقة بالكامل — بما فيها القوائم الطويلة
  // (التسليمات/الطلبة/الأكواد…) — في كل إطار تمرير تقريباً. هذا وحده هو سبب
  // التنافر والتنقز وبطء التمرير وفقدان مكان التمرير. القيمة لا تؤثر إطلاقاً إلا
  // على صنف CSS واحد (teacher-orbit-dock-shrunk) وسمة data على عنصري الشريط
  // (جوال/سطح مكتب)، ولا يقرأها أي منطق آخر في التطبيق. لذلك نحرّكها عبر ref مع
  // لمس DOM مباشر بلا إعادة رسم، مع الإبقاء على نفس اسم الدالة setIsDockShrunk
  // كي تبقى كل مواضع الاستدعاء ومنطق الانكماش/التوسّع وتصميم الشريط كما هي حرفياً.
  const dockShrunkRef = useRef(true);
  const applyDockShrunkToDom = () => {
    if (typeof document === "undefined") return;
    const shrunk = dockShrunkRef.current;
    const docks = document.querySelectorAll<HTMLElement>(".teacher-orbit-dock");
    docks.forEach((el) => {
      el.classList.toggle("teacher-orbit-dock-shrunk", shrunk);
      if (el.classList.contains("teacher-nav-mobile")) {
        el.setAttribute("data-miras-dock-state", shrunk ? "shrunk" : "open");
      }
    });
  };
  const setIsDockShrunk = (next: boolean) => {
    if (dockShrunkRef.current === next) return;
    dockShrunkRef.current = next;
    applyDockShrunkToDom();
  };
  // شبكة أمان: بعد كل رسم فعلي تُعاد مواءمة صنف/سمة الشريط مع قيمة الـ ref قبل
  // الطلاء (بلا وميض)، حتى لا يفقد الشريط حالته إن أعاد React رسمه لأسباب أخرى.
  useLayoutEffect(() => {
    applyDockShrunkToDom();
  });
  const dockShrinkTimerRef = useRef<number | null>(null);
  // كل تبديل تبويب يعيد التمرير لأعلى الصفحة برمجياً، وهذا وحده كان يُطلق
  // حدث scroll الذي يُعامَل كأنه تمرير حقيقي من المستخدم فيُشغّل مؤقّت انكماش
  // الشريط من جديد (بعد ١.٨ ثانية) — فإن وقعت الضغطة التالية على الشريط داخل
  // هذه النافذة، يتحرك الشريط (transform) في نفس لحظة اللمس فتضيع الضغطة على
  // الأجهزة الحقيقية. هذا العلَم يُسكت رد فعل التمرير على إعادة الضبط البرمجية
  // فقط، دون التأثير على انكماش/توسّع الشريط أثناء تمرير حقيقي فعلي.
  const suppressScrollDockRef = useRef(false);
  const clearTeacherDockShrinkTimer = () => {
    if (typeof window === "undefined") return;
    if (dockShrinkTimerRef.current) {
      window.clearTimeout(dockShrinkTimerRef.current);
      dockShrinkTimerRef.current = null;
    }
  };
  const expandTeacherDockNow = () => {
    clearTeacherDockShrinkTimer();
    setIsDockShrunk(false);
  };
  const shrinkTeacherDockSoon = (delay = 950) => {
    if (typeof window === "undefined") return;
    clearTeacherDockShrinkTimer();
    dockShrinkTimerRef.current = window.setTimeout(() => {
      setIsDockShrunk(true);
      dockShrinkTimerRef.current = null;
    }, delay);
  };

  useEffect(() => {
    return () => clearTeacherDockShrinkTimer();
  }, []);

  useEffect(() => {
    if (currentView === "teacher_workspace") {
      setIsDockShrunk(true);
    } else {
      setIsDockShrunk(false);
    }
  }, [currentView]);

  useEffect(() => {
    if (typeof window === "undefined" || typeof document === "undefined")
      return;

    let lastScrollY = window.scrollY;
    let ticking = false;
    let idleTimer = 0;

    const isTeacherWorkspace = () => currentView === "teacher_workspace";

    const readTeacherScrollY = () => {
      const main = document.querySelector(
        ".teacher-command-main",
      ) as HTMLElement | null;
      const shell = document.querySelector(
        ".meras-teacher-shell.teacher-calm-shell",
      ) as HTMLElement | null;
      const localY = Math.max(main?.scrollTop || 0, shell?.scrollTop || 0);
      return Math.max(
        window.scrollY || 0,
        document.documentElement.scrollTop || 0,
        document.body.scrollTop || 0,
        localY,
      );
    };

    const clearIdleTimer = () => {
      if (idleTimer) {
        window.clearTimeout(idleTimer);
        idleTimer = 0;
      }
    };

    const shrinkLater = (delay = 1150) => {
      clearIdleTimer();
      if (!isTeacherWorkspace()) return;
      idleTimer = window.setTimeout(() => {
        if (isTeacherWorkspace()) setIsDockShrunk(true);
      }, delay);
    };

    const expandDock = () => {
      if (!isTeacherWorkspace()) return;
      clearIdleTimer();
      setIsDockShrunk(false);
    };

    const updateScrollDir = () => {
      if (!isTeacherWorkspace()) {
        setIsDockShrunk(false);
        ticking = false;
        return;
      }

      const scrollY = readTeacherScrollY();
      if (scrollY > 40) {
        if (scrollY > lastScrollY + 2) {
          setIsDockShrunk(true);
        } else if (scrollY < lastScrollY - 12) {
          expandDock();
          shrinkLater(1500);
        }
      } else {
        expandDock();
        shrinkLater(1800);
      }
      lastScrollY = Math.max(0, scrollY);
      ticking = false;
    };

    const onScroll = () => {
      if (suppressScrollDockRef.current) return;
      if (!ticking) {
        window.requestAnimationFrame(updateScrollDir);
        ticking = true;
      }
    };

    const main = document.querySelector(
      ".teacher-command-main",
    ) as HTMLElement | null;
    const shell = document.querySelector(
      ".meras-teacher-shell.teacher-calm-shell",
    ) as HTMLElement | null;

    window.addEventListener("scroll", onScroll, { passive: true });
    document.addEventListener("scroll", onScroll, {
      passive: true,
      capture: true,
    });
    main?.addEventListener("scroll", onScroll, { passive: true });
    shell?.addEventListener("scroll", onScroll, { passive: true });

    if (isTeacherWorkspace()) shrinkLater(1600);

    return () => {
      clearIdleTimer();
      window.removeEventListener("scroll", onScroll);
      document.removeEventListener("scroll", onScroll, true);
      main?.removeEventListener("scroll", onScroll);
      shell?.removeEventListener("scroll", onScroll);
    };
  }, [currentView]);

