  // نافذة ثقة قصيرة بعد نجاح كود المقرر مباشرة: تمنع الاستطلاع الحيّ البطيء
  // من إعادة الكرت إلى حالة القفل قبل أن يلحق الخادم بتحديث الالتحاق.
  const recentlyActivatedCourseCodesRef = useRef<Record<string, number>>({});
  // practiceSubTab toggles between quizzes and exercises within the practice page
  const [practiceSubTab, setPracticeSubTab] = useState<"quizzes" | "exercises">(
    "quizzes",
  );
  const [teacherTab, setTeacherTab] = useState<
    | "home"
    | "students"
    | "textbook"
    | "questions"
    | "sections"
    | "analytics"
    | "codes"
    | "submissions"
  >("home");
  useEffect(() => {
    if (currentView !== "teacher_workspace") return;
    // يُسكت مؤقتاً رد فعل التمرير على إعادة الضبط البرمجية أدناه (راجع تعريف
    // suppressScrollDockRef)؛ يُرفع بعد مهلة تغطي كلا الاستدعاءين (الفوري
    // وrAF) وأي حدث scroll غير متزامن ناتج عنهما.
    suppressScrollDockRef.current = true;
    const unsuppressTimer = window.setTimeout(() => {
      suppressScrollDockRef.current = false;
    }, 300);
    const resetTeacherScroll = () => {
      try {
        const teacherMain = document.querySelector(
          ".teacher-command-main",
        ) as HTMLElement | null;
        teacherMain?.scrollTo?.({ top: 0, left: 0, behavior: "auto" });
        if (teacherMain) teacherMain.scrollTop = 0;
      } catch {}
      try {
        window.scrollTo({ top: 0, left: 0, behavior: "auto" });
      } catch {
        try {
          window.scrollTo(0, 0);
        } catch {}
      }
    };
    resetTeacherScroll();
    const raf = window.requestAnimationFrame(resetTeacherScroll);
    return () => {
      window.cancelAnimationFrame(raf);
      window.clearTimeout(unsuppressTimer);
      suppressScrollDockRef.current = false;
    };
  }, [currentView, teacherTab]);

  // يقيس الهيدر الفعلي المعروض على شاشة المعلّم (سواء الهيدر المضغوط للجوال أو
  // الهيدر العادي) ويضبط مسافة أعلى منطقة المحتوى لتطابق ارتفاعه بالضبط، بدل
  // الاعتماد على رقم تقديري ثابت قد يترك فراغاً أو يقصّ المحتوى تحت الهيدر.
  useEffect(() => {
    if (currentView !== "teacher_workspace" || typeof window === "undefined")
      return;

    const main = document.querySelector(
      ".teacher-command-main",
    ) as HTMLElement | null;
    if (!main) return;

    const isVisible = (el: HTMLElement | null) => {
      if (!el) return false;
      const style = window.getComputedStyle(el);
      if (style.display === "none" || style.visibility === "hidden")
        return false;
      const rect = el.getBoundingClientRect();
      return rect.width > 0 && rect.height > 0;
    };

    const dockBottomOffset = "calc(0.6rem + env(safe-area-inset-bottom, 0px))";

    const measure = () => {
      const zeroHeader = document.querySelector(
        ".miras-mobile-teacher-zero-header",
      ) as HTMLElement | null;
      // الهيدر المختصر وحده Overlay ثابت على الجوال ويحتاج مساحة محجوزة.
      // الهيدر المكتبي موجود أصلاً داخل تدفق main؛ قياس rect.bottom له ثم
      // إضافته كـ padding-top كان يصنع حلقة تغذية راجعة مع ResizeObserver:
      // كل padding يدفع الهيدر لأسفل، ثم القياس التالي يضاعفه حتى يصل إلى
      // آلاف البكسلات فتبدو الشاشة الكبيرة فارغة رغم نجاح تسجيل الدخول.
      if (isVisible(zeroHeader)) {
        const rect = zeroHeader!.getBoundingClientRect();
        const space =
          Math.ceil(rect.bottom - main.getBoundingClientRect().top) + 12;
        main.style.setProperty("padding-top", `${space}px`, "important");
        main.style.setProperty("scroll-padding-top", `${space}px`, "important");
      } else {
        main.style.removeProperty("padding-top");
        main.style.removeProperty("scroll-padding-top");
      }

      const dock = document.querySelector(
        ".miras-teacher-nav-shell.teacher-nav-mobile, .teacher-nav-mobile.teacher-orbit-dock",
      ) as HTMLElement | null;
      if (isVisible(dock)) {
        dock!.style.setProperty("bottom", dockBottomOffset, "important");
        // Use the dock's resting CSS position + its untransformed layout
        // height instead of getBoundingClientRect(): the shrink/expand
        // "breathing" animation moves the dock purely via a CSS transform,
        // so measuring its live transformed rect fed this padding back into
        // the scroll container mid-animation and made both the reserved
        // space and the bar itself flicker while scrolling. Neither value
        // used below changes with that transform, so the clearance — and the
        // bar's apparent position — now stay stable during scroll.
        const dockRestBottom =
          parseFloat(window.getComputedStyle(dock!).bottom) || 0;
        // Cushion above the dock: keep the dock untouched, but give the
        // final mobile cards enough breathing room on compact teacher pages.
        const bottomSpace = Math.max(
          168,
          Math.ceil(dockRestBottom + dock!.offsetHeight) + 64,
        );
        main.style.setProperty(
          "--miras-teacher-bottom-safe-space",
          `${bottomSpace}px`,
        );
        main.style.setProperty("--miras-teacher-bottom-extra-cushion", "64px");
        main.style.setProperty(
          "padding-bottom",
          `${bottomSpace}px`,
          "important",
        );
        main.style.setProperty(
          "scroll-padding-bottom",
          `${bottomSpace}px`,
          "important",
        );
      } else {
        dock?.style.removeProperty("bottom");
        main.style.removeProperty("--miras-teacher-bottom-safe-space");
        main.style.removeProperty("--miras-teacher-bottom-extra-cushion");
        main.style.removeProperty("padding-bottom");
        main.style.removeProperty("scroll-padding-bottom");
      }
    };

    const raf = window.requestAnimationFrame(measure);
    const delayedMeasure = window.setTimeout(measure, 340);
    const visualViewport = window.visualViewport;
    window.addEventListener("resize", measure);
    window.addEventListener("orientationchange", measure);
    visualViewport?.addEventListener("resize", measure);
    // احتياط: خط الطباعة العربي أو اسم أستاذ طويل قد يغيّر ارتفاع الهيدر بعد
    // انتهاء المؤقتات أعلاه، فيصبح الفراغ العلوي المحجوز أقصر من الهيدر الفعلي
    // ويظهر طرف من المحتوى المُمرَّر خلفه. المراقب هذا يعيد القياس فوراً كلما
    // تغيّر ارتفاع الهيدر لأي سبب.
    const headerResizeObserver =
      typeof ResizeObserver !== "undefined"
        ? new ResizeObserver(measure)
        : null;
    const zeroHeaderEl = document.querySelector(
      ".miras-mobile-teacher-zero-header",
    );
    if (zeroHeaderEl) headerResizeObserver?.observe(zeroHeaderEl);
    return () => {
      window.cancelAnimationFrame(raf);
      window.clearTimeout(delayedMeasure);
      window.removeEventListener("resize", measure);
      window.removeEventListener("orientationchange", measure);
      visualViewport?.removeEventListener("resize", measure);
      headerResizeObserver?.disconnect();
      main.style.removeProperty("padding-top");
      main.style.removeProperty("scroll-padding-top");
      main.style.removeProperty("padding-bottom");
      main.style.removeProperty("scroll-padding-bottom");
      const dock = document.querySelector(
        ".miras-teacher-nav-shell.teacher-nav-mobile, .teacher-nav-mobile.teacher-orbit-dock",
      ) as HTMLElement | null;
      dock?.style.removeProperty("bottom");
    };
  }, [currentView, teacherTab, teacherSession?.name]);
