  // ===========================================================================
  // (٢) إخفاء بريد المعلّم ورقم المقرر من كامل الموقع دون استثناء: طبقة تعقيم عامة
  // على مستوى العرض تستبدل البريد باسم المعلّم، ورقم/رمز المقرر باسم المقرر، في كل
  // الصفحات والكروت والنوافذ. تعدّل قيمة العقدة النصية فقط (لا تضيف/تحذف عُقَداً)
  // فلا تتعارض مع React، وتتخطّى حقول الإدخال والأكواد المباعة (أكواد التفعيل).
  // ===========================================================================
  useEffect(() => {
    if (typeof document === "undefined" || !document.body) return;

    // بناء خرائط: بريد → اسم معلّم، ورمز مقرر → اسم مقرر، من البيانات المحمّلة.
    const emailMap = new Map<string, string>();
    const addEmail = (email: any, name: any) => {
      const e = String(email || "")
        .trim()
        .toLowerCase();
      if (!e || !e.includes("@")) return;
      const n = String(name || "").trim();
      if (!emailMap.has(e))
        emailMap.set(e, n && !n.includes("@") ? n : "المعلّم");
    };
    if (teacherSession) addEmail(teacherSession.email, teacherSession.name);

    const codeMap = new Map<string, string>();
    const addCode = (code: any) => {
      const raw = stripOwnerEmailFromCourseCode(String(code || "")).trim();
      if (raw.length < 3) return; // تجنّب مطابقة أرقام قصيرة عامة
      const key = raw.toLowerCase();
      if (codeMap.has(key)) return;
      const name = courseNameForCode(raw);
      if (
        name &&
        isHumanCourseLabel(name, raw) &&
        name.trim().toLowerCase() !== key
      ) {
        codeMap.set(key, name.trim());
      }
    };
    (Array.isArray(teacherSections) ? teacherSections : []).forEach(
      (sec: any) => {
        [
          sec?.ownerEmail,
          sec?.teacherEmail,
          sec?.createdByEmail,
          extractEmailFromCourseCode(sec?.code),
        ].forEach((em: any) => addEmail(em, teacherDisplayNameForMessage(em)));
        [
          sec?.code,
          sec?.courseCode,
          sec?.sectionCode,
          sec?.courseNumber,
          sec?.courseId,
          sec?.subjectCode,
        ].forEach(addCode);
      },
    );
    (Array.isArray(studentEnrollments) ? studentEnrollments : []).forEach(
      (en: any) => {
        [en?.courseCode, en?.sectionCode, en?.studentSection].forEach(addCode);
      },
    );

    if (!emailMap.size && !codeMap.size) return;

    const escapeRe = (s: string) => s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
    const tokens = [...emailMap.keys(), ...codeMap.keys()]
      .sort((a, b) => b.length - a.length)
      .map(escapeRe);
    const pattern = new RegExp(
      "(?<![\\w.@-])(" + tokens.join("|") + ")(?![\\w.@-])",
      "gi",
    );
    const mapToken = (tok: string) => {
      const k = tok.toLowerCase();
      return emailMap.get(k) ?? codeMap.get(k) ?? tok;
    };

    const SKIP_TAGS = new Set([
      "INPUT",
      "TEXTAREA",
      "SCRIPT",
      "STYLE",
      "SELECT",
      "OPTION",
    ]);
    const inSkippedZone = (node: Node) => {
      let el: HTMLElement | null = node.parentElement;
      while (el) {
        if (SKIP_TAGS.has(el.tagName) || el.isContentEditable) return true;
        el = el.parentElement;
      }
      return false;
    };
    const sanitizeTextNode = (node: Text) => {
      const val = node.nodeValue;
      if (!val || val.length < 3) return;
      pattern.lastIndex = 0;
      if (!pattern.test(val)) return;
      if (inSkippedZone(node)) return;
      pattern.lastIndex = 0;
      const next = val.replace(pattern, (m) => mapToken(m));
      if (next !== val) node.nodeValue = next;
    };
    const walk = (root: Node) => {
      if (root.nodeType === Node.TEXT_NODE) {
        sanitizeTextNode(root as Text);
        return;
      }
      if (root.nodeType !== Node.ELEMENT_NODE) return;
      const el = root as HTMLElement;
      if (SKIP_TAGS.has(el.tagName) || el.isContentEditable) return;
      const tw = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
      let n: Node | null;
      const batch: Text[] = [];
      while ((n = tw.nextNode())) batch.push(n as Text);
      batch.forEach(sanitizeTextNode);
    };

    let observer: MutationObserver | null = null;
    let scheduled = false;
    const pending: Node[] = [];
    const flush = () => {
      scheduled = false;
      if (!observer) return;
      observer.disconnect();
      const nodes = pending.splice(0, pending.length);
      nodes.forEach(walk);
      observer.observe(document.body, {
        childList: true,
        subtree: true,
        characterData: true,
      });
    };
    const schedule = (node: Node) => {
      pending.push(node);
      if (!scheduled) {
        scheduled = true;
        setTimeout(flush, 120);
      }
    };

    walk(document.body); // كنس أولي شامل
    observer = new MutationObserver((records) => {
      for (const r of records) {
        if (r.type === "characterData") schedule(r.target);
        else r.addedNodes.forEach((added) => schedule(added));
      }
    });
    observer.observe(document.body, {
      childList: true,
      subtree: true,
      characterData: true,
    });
    return () => {
      if (observer) observer.disconnect();
    };
  }, [teacherSections, teacherSession, studentEnrollments, currentView]);
  const isAppStandalone =
    typeof window !== "undefined" &&
    (window.matchMedia("(display-mode: standalone)").matches ||
      !!(window.navigator as any).standalone);
  const [showPwaBanner, setShowPwaBanner] = useState(false);
