  const mergeJoinCodeRecords = (primary: any[] = [], secondary: any[] = []) => {
    const merged = new Map<string, any>();
    const put = (item: any) => {
      if (!item) return;
      const key = compactJoinCode(item.code || item.id || "");
      if (!key) return;
      merged.set(key, { ...(merged.get(key) || {}), ...item });
    };
    primary.forEach(put);
    secondary.forEach((item: any) => {
      const key = compactJoinCode(item?.code || item?.id || "");
      if (key && !merged.has(key)) put(item);
    });
    return Array.from(merged.values());
  };
