  const announceStudentLiveSync = (reason: string) => {
    const signal = {
      type: "MIRAS_STUDENT_LIVE_SYNC",
      reason,
      at: Date.now(),
    };
    try {
      window.dispatchEvent(
        new CustomEvent("miras-student-live-sync", { detail: signal }),
      );
    } catch {}
    try {
      localStorage.setItem(MIRAS_STUDENT_LIVE_SYNC_KEY, JSON.stringify(signal));
    } catch {}
    try {
      const channel = new BroadcastChannel(MIRAS_STUDENT_LIVE_CHANNEL);
      channel.postMessage(signal);
      channel.close();
    } catch {}
  };

  useEffect(() => {
    if (typeof navigator === "undefined" || !("serviceWorker" in navigator))
      return;
    const handleServiceWorkerMessage = (event: MessageEvent) => {
      if (
        event.data?.type !== "MIRAS_FCM_IN_APP_NOTIFICATION" &&
        event.data?.type !== "MIRAS_FCM_PENDING_NOTIFICATIONS" &&
        event.data?.type !== "MIRAS_STUDENT_LIVE_SYNC"
      )
        return;
      const identity = currentNotificationIdentity();
      if (!identity?.userId) return;
      if (event.data?.type === "MIRAS_STUDENT_LIVE_SYNC") {
        if (identity.role === "student") {
          announceStudentLiveSync(
            event.data?.reason || "service-worker-live-sync",
          );
          refreshStudentLiveState().catch(() => undefined);
        }
        return;
      }
      const payloads =
        event.data?.type === "MIRAS_FCM_PENDING_NOTIFICATIONS"
          ? event.data?.payloads || []
          : [event.data?.payload || {}];
      const normalized = (Array.isArray(payloads) ? payloads : [])
        .filter(Boolean)
        .filter((payload: any) =>
          fcmPayloadTargetsCurrentIdentity(payload, identity),
        )
        .map((payload: any) =>
          normalizeLocalNotification({
            ...payload,
            source: payload.source || payload.data?.source || "fcm",
            sectionCode:
              payload.sectionCode ||
              payload.courseCode ||
              payload.data?.sectionCode ||
              payload.data?.courseCode ||
              "",
            courseCode:
              payload.courseCode ||
              payload.sectionCode ||
              payload.data?.courseCode ||
              payload.data?.sectionCode ||
              "",
            data: {
              ...(payload.data || {}),
              source: payload.data?.source || payload.source || "fcm",
            },
          }),
        );
      mergeLocalNotifications(
        normalized,
        identity.role === "student"
          ? notificationTargetsStudent
          : notificationTargetsTeacher,
      );
      fetchInAppNotifications().catch(() => undefined);
      if (identity.role === "student") {
        announceStudentLiveSync(
          event.data?.type === "MIRAS_FCM_PENDING_NOTIFICATIONS"
            ? "service-worker-pending"
            : "service-worker-message",
        );
        refreshStudentLiveState().catch(() => undefined);
      }
    };
    navigator.serviceWorker.addEventListener(
      "message",
      handleServiceWorkerMessage,
    );
    navigator.serviceWorker.ready
      .then((registration) => {
        try {
          registration.active?.postMessage({ type: "MIRAS_FLUSH_PENDING_FCM" });
        } catch {}
      })
      .catch(() => undefined);
    return () => {
      navigator.serviceWorker.removeEventListener(
        "message",
        handleServiceWorkerMessage,
      );
    };
  }, [studentSession?.id, teacherSession?.email]);
