    // مطابقة واعية بالمالك (مثل السيرفر تماماً): مقرران بنفس الرقم لكن لمعلّمَين
    // مختلفين ليسا نفس المقرر. بدون هذا، أكواد مثل 111-aa@… و111-bb@… كانت
    // تُدمج معاً (لأن لهما نفس الرقم "111") فيختفي أحد المقررين من حساب الطالب.
    const aOwner = extractEmailFromCourseCode(aRaw);
    const bOwner = extractEmailFromCourseCode(bRaw);
    if (aOwner && bOwner && aOwner !== bOwner) return false;
    const aa = courseCodeAliases(aRaw);
