  const reloadTeacherDashboard = async (emailOverride?: string) => {
    // كانت هذه الطلبات تُنتظر بالتسلسل (reports ثم logs ٣٦٤ك ثم config ثم
    // questionBank) فيتراكم زمنها؛ وهي مستقلة تماماً فنشغّلها بالتوازي لتقليل زمن
    // تحميل اللوحة إلى زمن أبطأ طلب فقط بدل مجموعها.
    const email = emailOverride || teacherSession?.email || "";
    const refreshQuota = async () => {
      try {
        const quotaResp = await fetch("/api/config/firebase-public", {
          cache: "no-store",
        });
        const quotaData = await quotaResp.json();
        setFirestoreQuotaExceededState(!!quotaData.firestoreQuotaExceeded);
      } catch (err) {
        console.warn("Failed to update database quota status on refresh:", err);
      }
    };
    await Promise.allSettled([
      fetchReports(email),
      fetchLogs(email),
      fetchQuestionBank(email),
      refreshQuota(),
    ]);
  };

  const handleDatabaseReset = async (type: "custom" | "full") => {
    const confirmed = await confirmAdminPasskeyForSensitiveAction(
      type === "full" ? "التصفير الكامل" : "التصفير المخصص",
    );
    if (!confirmed) return;
    setDbResetLoading(true);
    setDbResetStatus(null);
    try {
      const email = teacherSession?.email || "";
      const res = await fetch(`/api/teacher/database/${type}-reset`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "X-Teacher-Email": email,
        },
        body: JSON.stringify({ teacherEmail: email }),
      });

      const data = await res.json();
      if (res.ok && data.success) {
        setDbResetStatus({
          success: true,
          message: sanitizeCourseIdentifiersForDisplay(data.message),
        });
        clearTransientUploadedData();
        clearTeacherStateAfterDatabaseReset();

        // أعد بناء كل القوائم من السحابة بعد تصفير state والكاش المحلي.
        // هذا يمنع بقاء أرقام من الجلسة السابقة فوق قاعدة بيانات فارغة.
        await Promise.allSettled([
          fetchSections(email),
          fetchChapters(),
          fetchQuestionBank(),
          fetchTeacherExams(),
          fetchTeacherProjects(),
          fetchTeacherSubmissions(),
          fetchJoinCodes(email),
          fetchPasswordResetRequests(email),
          fetchLogs(),
          fetchReports(),
          fetchCodeIntegrity(email),
        ]);

        // Hide confirmation dialogs
        setShowCustomResetConfirm(false);
        setShowFullResetConfirm(false);
      } else {
        setDbResetStatus({
          success: false,
          message: sanitizeCourseIdentifiersForDisplay(
            data.error || "فشل غير معروف في معالجة طلب التصفير.",
          ),
        });
      }
    } catch (err: any) {
      setDbResetStatus({
        success: false,
        message: "فشل في الاتصال بالخادم: " + err.message,
      });
    } finally {
      setDbResetLoading(false);
    }
  };

  const handleAllowedExcelUpload = async (e: any) => {
    const file = e?.target?.files?.[0];
    if (!file) return;
    try {
      const lowerName = String(file.name || "").toLowerCase();
      if (lowerName.endsWith(".xml")) {
        const xmlText = await file.text();
        const parsed = parseMoodleQuestionBankXml(xmlText);
        if (!parsed.length) {
          setErrorMsg("لم يتم العثور على أسئلة صالحة داخل ملف Moodle XML.");
          return;
        }
        setQuestionRawRows([]);
        setQuestionColumns(["Moodle XML"]);
        setQuestionImportPreview(parsed);
        setQuestionImportErrors([]);
        setQuestionImportOpen(true);
        setSuccessMsg(
          `تمت قراءة ملف Moodle XML بنفس صيغة الاختبار، وعدد الأسئلة الجاهزة: ${parsed.length}.`,
        );
        return;
      }
      const buffer = await file.arrayBuffer();
      const XLSX = await import("xlsx");
      const workbook = XLSX.read(buffer, {
        type: "array",
        raw: false,
        codepage: 65001,
      });
      const sheet = workbook.Sheets[workbook.SheetNames[0]];
      const rows: any[][] = XLSX.utils.sheet_to_json(sheet, {
        header: 1,
        defval: "",
        raw: false,
      });
      const nonEmpty = rows
        .map((r, idx) => ({
          idx: idx + 1,
          cells: r.map((c) => repairArabicText(c)),
        }))
        .filter((r) => r.cells.some(Boolean));
      if (!nonEmpty.length) {
        setErrorMsg(
          "ملف Excel فارغ. ارفع ملفاً يحتوي على اسم الطالب والرقم الجامعي.",
        );
        return;
      }
      const header = nonEmpty[0].cells;
      const maxCols = Math.max(...nonEmpty.map((r) => r.cells.length));
      const labels = Array.from({ length: maxCols }).map(
        (_, i) => header[i] || `عمود ${i + 1}`,
      );
      const lower = labels.map((x) => String(x).toLowerCase());
      const guessedName = lower.findIndex(
        (c) => c.includes("اسم") || c.includes("name"),
      );
      const guessedId = lower.findIndex(
        (c) => c.includes("رقم") || c.includes("id") || c.includes("student"),
      );
      setExcelColumns(labels);
      setExcelPendingRows(nonEmpty);
      setExcelImportReady(false);
      setExcelNameCol(guessedName >= 0 ? guessedName : 0);
      setExcelIdCol(guessedId >= 0 ? guessedId : Math.min(1, maxCols - 1));
      setExcelMappingOpen(true);
      setSuccessMsg(
        "تمت قراءة ملف Excel. سيتم تجاهل الصف الأول باعتباره عناوين، حدد عمود الاسم وعمود الرقم الجامعي ثم اعتمد الاستيراد.",
      );
    } catch (err) {
      setErrorMsg(
        "تعذر قراءة ملف Excel. تأكد من صيغة الملف .xlsx أو .xls أو .csv.",
      );
    } finally {
      if (excelFileInputRef.current) excelFileInputRef.current.value = "";
    }
  };

  const parseAllowedExcelRows = () => {
    const activeCourse =
      activeCourseCode || selectedTeacherCourseCode || "TECH-A1";
    if (excelNameCol === excelIdCol) {
      return {
        parsed: [],
        error: "اختر عمودين مختلفين: عمود للاسم وعمود للرقم الجامعي.",
      };
    }

    // الصف الأول في ملفات الكشوف يكون عادة صف عناوين، لذلك يُستبعد دائماً من الاستيراد.
    // أي صف لاحق غير مكتمل أو يبدو كعنوان/ملاحظة يتم تجاوزه بهدوء بدلاً من إيقاف العملية كاملة.
    const rows = excelPendingRows.slice(1);
    const parsed: any[] = [];
    const skippedRows: number[] = [];
    const seenIds = new Set<string>();
    const duplicateIds = new Set<string>();

    rows.forEach((row) => {
      const name = repairArabicText(row.cells[excelNameCol]);
      const idNumber = String(row.cells[excelIdCol] || "")
        .replace(/\s/g, "")
        .trim();
      const joinedCells = row.cells
        .map((cell: any) => String(cell || "").trim())
        .filter(Boolean)
        .join(" ")
        .toLowerCase();
      const looksLikeHeader =
        joinedCells.includes("اسم الطالب") ||
        joinedCells.includes("الطلبة") ||
        joinedCells.includes("student name") ||
        joinedCells.includes("student id") ||
        joinedCells.includes("الرقم الجامعي");

      if (!name && !idNumber) return;
      if (looksLikeHeader || !name || !/^\d{4,}$/.test(idNumber)) {
        skippedRows.push(row.idx);
        return;
      }
      if (seenIds.has(idNumber)) duplicateIds.add(idNumber);
      seenIds.add(idNumber);
      parsed.push({ idNumber, name, sectionCode: activeCourse });
    });

    if (!parsed.length) {
      return {
        parsed: [],
        error:
          "لم يتم العثور على طلبة صالحين بعد تجاهل صف العناوين والصفوف غير المكتملة. تأكد من اختيار عمود الاسم وعمود الرقم الجامعي بشكل صحيح.",
      };
    }
    if (duplicateIds.size) {
      return {
        parsed: [],
        error: `لا يمكن اعتماد الملف: يوجد أرقام جامعية مكررة (${Array.from(duplicateIds).slice(0, 5).join("، ")}).`,
      };
    }
    return { parsed, error: "", skippedRows };
  };

  const mergeAllowedRosterTextForCourse = (
    incomingRows: any[],
    courseCode: string,
  ) => {
    const otherRows = parseAllowedRosterText().filter(
      (row: any) => String(row.sectionCode) !== String(courseCode),
    );
    const merged = [
      ...otherRows,
      ...incomingRows.map((r: any) => ({
        idNumber: r.idNumber,
        name: r.name,
        sectionCode: courseCode,
      })),
    ];
    return merged
      .map((r: any) => `${r.idNumber}, ${r.name}, ${r.sectionCode}`)
      .join("\n");
  };

  const applyAllowedExcelMapping = async () => {
    setErrorMsg("");
    setSuccessMsg("");
    const activeCourse =
      activeCourseCode || selectedTeacherCourseCode || "TECH-A1";
    const result = parseAllowedExcelRows();
    if (result.error) {
      setExcelImportReady(false);
      setErrorMsg(result.error);
      return;
    }
    setAllowedStudentsText(
      mergeAllowedRosterTextForCourse(result.parsed, activeCourse),
    );
    setExcelImportReady(true);
    setExcelMappingOpen(false);
    await handleUpdateAllowedStudents(result.parsed);
    if ((result as any).skippedRows?.length) {
      setSuccessMsg(
        `تم اعتماد ${result.parsed.length} طالب، وتم تجاوز الصفوف غير المكتملة أو صفوف العناوين: ${(result as any).skippedRows.slice(0, 8).join("، ")}${(result as any).skippedRows.length > 8 ? "..." : ""}`,
      );
    } else {
      setSuccessMsg(
        `تم اعتماد ${result.parsed.length} طالب بعد تجاهل الصف الأول من ملف Excel باعتباره صف عناوين.`,
      );
    }
  };

  const handleUpdateAllowedStudents = async (preParsedList?: any[]) => {
    setErrorMsg("");
    setSuccessMsg("");
    try {
      // Parse CSV Text: idNumber, name, sectionCode
      const parsedList =
        preParsedList ||
        allowedStudentsText
          .trim()
          .split("\n")
          .map((line) => {
            const parts = line.split(",");
            return {
              idNumber: parts[0]?.trim() || "",
              name: repairArabicText(parts[1] || ""),
              sectionCode:
                parts[2]?.trim() || selectedTeacherCourseCode || "TECH-A1",
            };
          })
          .filter((s) => s.idNumber.length > 3);

      const seen = new Set<string>();
      const duplicates = new Set<string>();
      parsedList.forEach((student: any) => {
        if (seen.has(student.idNumber)) duplicates.add(student.idNumber);
        seen.add(student.idNumber);
      });
      const targetCloudCourse = String(
        parsedList[0]?.sectionCode ||
          selectedTeacherCourseCode ||
          activeCourseCode ||
          "",
      ).trim();
      if (!parsedList.length && !targetCloudCourse) {
        setErrorMsg("اختر المقرر قبل حفظ كشف الطلاب على السحابة.");
        return;
      }
      if (duplicates.size) {
        setErrorMsg(
          `لا يمكن اعتماد كشف الطلاب: يوجد أرقام جامعية مكررة (${Array.from(duplicates).slice(0, 5).join("، ")}).`,
        );
        return;
      }

      const cloudRows = parsedList
        .map((row: any) => ({
          idNumber: String(row.idNumber || "").trim(),
          name: String(row.name || "").trim(),
          sectionCode: String(row.sectionCode || targetCloudCourse).trim(),
        }))
        .filter((row: any) => row.idNumber && row.name && row.sectionCode);
      const resp = await fetch("/api/teacher/upload-allowed", {
        method: "POST",
        headers: teacherHeaders(),
        body: JSON.stringify({
          studentsList: cloudRows,
          sectionCode: targetCloudCourse,
        }),
      });
      const d = await resp.json().catch(() => ({}));
      if (!resp.ok) {
        setErrorMsg(
          d.error ||
            "فشل حفظ كشف الطلبة على السحابة. لم يتم اعتماد أي كشف بديل؛ أعد المحاولة بعد التأكد من الاتصال.",
        );
        return;
      }
      setSuccessMsg(
        `تم حفظ كشف الطلاب على السحابة واعتماده تحت المقرر المحدد بـ (${cloudRows.length}) طالباً.`,
      );
      if (Array.isArray(d.allowedStudents)) {
        setAllowedStudentsText(
          allowedRosterRowsToText(mergeRosterRowsById(d.allowedStudents)),
        );
      }
      await fetchReports();
      setExcelPendingRows([]);
      setExcelColumns([]);
      setExcelImportReady(false);
    } catch (e) {
      setErrorMsg("فشل معالجة صيغة نص الطلاب");
    }
  };

  // Protected source upload: real file selection, stored server-side, never exposed to students
  const handleSimulatedBookUpload = async (e: any) => {
    const file = e?.target?.files?.[0];
    if (!file) return;
    if (
      file.type !== "application/pdf" &&
      !file.name.toLowerCase().endsWith(".pdf")
    ) {
      setErrorMsg("يرجى رفع ملف PDF فقط.");
      return;
    }

    setIsUploadingBook(true);
    setErrorMsg("");
    try {
      const fileData = await new Promise<string>((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = () => resolve(String(reader.result));
        reader.onerror = () => reject(reader.error);
        reader.readAsDataURL(file);
      });

      const resp = await fetch("/api/teacher/textbook/upload", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          fileName: file.name,
          size: `${(file.size / (1024 * 1024)).toFixed(2)} MB`,
          fileData,
        }),
      });
      const d = await resp.json();
      if (d.success) {
        setBookMetadata(d.metadata);
        setSuccessMsg(
          "تم رفع PDF وحفظه كمصدر محمي. اضغط تحليل المصدر لبناء الخريطة محليًا مجانًا.",
        );
        fetchChapters();
      } else {
        setErrorMsg(d.error || "تعذر رفع المصدر.");
      }
    } catch (err) {
      console.error(err);
      setErrorMsg("فشل رفع ملف PDF. يرجى إعادة المحاولة.");
    } finally {
      setIsUploadingBook(false);
      if (e?.target) e.target.value = "";
    }
  };

