                                            <div className="min-w-0 flex-1">
                                              <div className="text-[12px] font-medium leading-7 text-slate-800">
                                                {cleanTitle}
                                              </div>
                                              {block.score && (
                                                <div className="mt-1 text-[10px] font-light text-slate-400">
                                                  درجة السؤال: {block.score}
                                                </div>
                                              )}
                                            </div>
